import sys, json, random, importlib.util
sys.path.insert(0, '/workspace/tests')
import ref

spec = importlib.util.spec_from_file_location("entry", "/app/submission/entry.py")
entry = importlib.util.module_from_spec(spec)
spec.loader.exec_module(entry)


def run_impl(traces_doc):
    text = json.dumps(traces_doc)
    tr = entry.parse_document(text)
    out = []
    for (tid, cfg, events) in tr:
        rp = entry.Replay(tid, cfg, events)
        rp.run()
        out.append(rp.result())
    return out


def gen_config(rng):
    sent = {}
    for k in ("I", "H", "A"):
        n = rng.randint(0, 3)
        out = []
        nxt = 0
        for _ in range(n):
            lo = nxt + rng.randint(0, 3)
            hi = lo + rng.randint(0, 3)
            out.append([lo, hi])
            nxt = hi + 2
        sent[k] = out
    return {
        "early": rng.random() < 0.5,
        "overlap": rng.choice(["reject", "first"]),
        "buffer_packets": rng.randint(0, 4),
        "idle_ms": rng.choice([0, 1, 3, 5, 10, 50]),
        "max_streams_bidi": rng.randint(0, 4),
        "max_streams_uni": rng.randint(0, 4),
        "max_stream_data": rng.choice([0, 1, 4, 8, 32]),
        "max_data": rng.choice([0, 4, 8, 16, 64, 10 ** 9]),
        "crypto_limit": rng.choice([0, 2, 4, 16]),
        "sent": sent,
    }


def gen_frame(rng, hexpool):
    ty = rng.choice(["PADDING", "PING", "ACK", "CRYPTO", "STREAM",
                     "RESET_STREAM", "STOP_SENDING", "CLOSE",
                     "HANDSHAKE_DONE", "UNKNOWN", "CRYPTO", "STREAM",
                     "STREAM", "ACK"])
    if ty in ("PADDING", "PING", "HANDSHAKE_DONE", "UNKNOWN"):
        return {"type": ty}
    if ty == "ACK":
        n = rng.randint(0, 3)
        rngs = []
        for i in range(n):
            lo = rng.randint(0, 12)
            hi = lo + rng.randint(0, 3)
            if rng.random() < 0.25:
                lo, hi = hi, lo
            rngs.append([lo, hi])
        if rng.random() < 0.2 and len(rngs) > 1:
            rngs.reverse()
        if rng.random() < 0.2 and len(rngs) > 1:
            rngs[-1] = [rngs[-2][0], rngs[-1][1]]
        return {"type": ty, "ranges": rngs}
    if ty == "CRYPTO":
        return {"type": ty, "offset": rng.randint(0, 8),
                "data_hex": hexpool()}
    if ty == "STREAM":
        return {"type": ty, "id": rng.choice([0, 0, 2, 4, 6, 8, 1, 3, 12]),
                "offset": rng.randint(0, 8), "data_hex": hexpool(),
                "fin": rng.random() < 0.3}
    if ty == "RESET_STREAM":
        return {"type": ty, "id": rng.choice([0, 0, 2, 4, 6, 1, 3]),
                "final_size": rng.randint(0, 9)}
    if ty == "STOP_SENDING":
        return {"type": ty, "id": rng.choice([0, 2, 4, 8, 1, 3])}
    return {"type": ty, "app": rng.random() < 0.5,
            "code": rng.choice([0, 1, 3, 7, 0x12, 4611686018427387903])}


def gen_trace(rng, tid, nev):
    cfg = gen_config(rng)
    events = []
    t = 0
    bytes_pool = ["", "00", "01", "02", "ff", "aa", "0102", "ffff", "00ff",
                  "aabb", "010203", "ff00"]
    def hexpool():
        if rng.random() < 0.1:
            return ""
        return rng.choice(bytes_pool)
    for _ in range(nev):
        t += rng.choice([0, 0, 1, 1, 2, 5, 9])
        kind = rng.choice(["key", "tick", "datagram", "datagram", "datagram",
                           "datagram"])
        if kind == "key":
            events.append({"t": t, "op": "key",
                           "level": rng.choice(list("IHZA")),
                           "action": rng.choice(["install", "discard",
                                                 "install"])})
        elif kind == "tick":
            events.append({"t": t, "op": "tick"})
        else:
            npk = rng.randint(1, 4)
            size = rng.choice([0, 1199, 1200, 1500])
            pkts = []
            for _ in range(npk):
                nfr = rng.randint(0, 4)
                frames = [gen_frame(rng, hexpool) for _ in range(nfr)]
                pkts.append({"level": rng.choice(list("IHZA")),
                             "pn": rng.randint(0, 6),
                             "auth": rng.random() < 0.85,
                             "frames": frames})
            events.append({"t": t, "op": "datagram", "bytes": size,
                           "packets": pkts})
    return {"id": tid, "config": cfg, "events": events}


def main(n=3000, seed=1):
    rng = random.Random(seed)
    bad = 0
    for it in range(n):
        traces = [gen_trace(rng, "t%d" % i, rng.randint(0, 12))
                  for i in range(rng.randint(1, 3))]
        doc = {"version": 1, "traces": traces}
        try:
            expect = [ref.replay(t) for t in traces]
        except Exception as exc:
            print("REF CRASH", repr(exc))
            print(json.dumps(doc))
            return 1
        try:
            got = run_impl(doc)
        except Exception as exc:
            print("IMPL CRASH", repr(exc))
            print(json.dumps(doc))
            return 1
        if got != expect:
            bad += 1
            if bad <= 3:
                print("MISMATCH iter", it)
                a = json.dumps(got)
                b = json.dumps(expect)
                print(" impl:", a[:1500])
                print(" ref :", b[:1500])
                for j in range(len(expect)):
                    def find(x, y, path=""):
                        if type(x) != type(y):
                            print("  type", path, x, y); return
                        if isinstance(x, dict):
                            for k in set(x) | set(y): find(x.get(k), y.get(k), path + "/" + k)
                        elif isinstance(x, list):
                            if len(x) != len(y):
                                print("  len", path, len(x), len(y)); return
                            for i2, (p, q) in enumerate(zip(x, y)): find(p, q, path + "/" + str(i2))
                        elif x != y:
                            print("  diff", path, repr(x)[:60], repr(y)[:60])
                    find(got[j], expect[j], "r%d" % j)
                print("doc:", json.dumps(doc))
                if bad >= 3:
                    return 1
    print("fuzz done: mismatches=%d of %d" % (bad, n))
    return 1 if bad else 0


if __name__ == "__main__":
    sys.exit(main(int(sys.argv[1]) if len(sys.argv) > 1 else 3000,
                  int(sys.argv[2]) if len(sys.argv) > 2 else 1))
